{"file_path":"src/diff.js","content":"/**
 * Longest common subsequence based diff between a "side" document (mine or
 * theirs) and the base document, following the tie-break rule from the
 * specification: when two subsequences would be equally long, prefer the one
 * whose matches occur earliest, breaking ties between advancing the side and
 * advancing the base in favour of the base.
 */

/**
 * @param {string[]} side
 * @param {string[]} base
 * @returns {{baseStart:number, baseEnd:number, sideStart:number, sideEnd:number}[]}
 *   A list of changes (hunks), ordered by base position, each describing a
 *   run of base lines replaced by a run of side lines.
 */
export function diffAgainstBase(side, base) {
  const m = side.length
  const n = base.length

  // dp[i][j] = length of the LCS of side[i:] and base[j:]
  const dp = new Array(m + 1)
  for (let i = 0; i <= m; i++) dp[i] = new Int32Array(n + 1)
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      dp[i][j] = side[i] === base[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const changes = []
  let i = 0
  let j = 0
  let open = null // { baseStart, sideStart }

  while (i < m || j < n) {
    if (i < m && j < n && side[i] === base[j]) {
      if (open) {
        changes.push({ baseStart: open.baseStart, baseEnd: j, sideStart: open.sideStart, sideEnd: i })
        open = null
      }
      i++
      j++
      continue
    }

    if (!open) open = { baseStart: j, sideStart: i }

    if (i < m && j < n) {
      if (dp[i + 1][j] > dp[i][j + 1]) {
        i++
      } else {
        j++
      }
    } else if (i < m) {
      i++
    } else {
      j++
    }
  }

  if (open) {
    changes.push({ baseStart: open.baseStart, baseEnd: j, sideStart: open.sideStart, sideEnd: i })
  }

  return changes
}
"}

