{"file_path":"src/merge.js","content":"import { diffAgainstBase } from './diff.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Builds a base-position -> side-position mapping function from a list of
 * changes (hunks) between `side` and `base`. The mapping is exact at every
 * change boundary and interpolated linearly through the stable stretches in
 * between (where side and base lines correspond 1:1).
 */
function makeMapper(changes, baseLen, sideLen) {
  const boundaries = [{ base: 0, side: 0 }]
  for (const c of changes) {
    boundaries.push({ base: c.baseStart, side: c.sideStart })
    boundaries.push({ base: c.baseEnd, side: c.sideEnd })
  }
  boundaries.push({ base: baseLen, side: sideLen })

  return function map(basePos) {
    let k = 0
    for (let idx = 0; idx < boundaries.length; idx++) {
      if (boundaries[idx].base <= basePos) k = idx
      else break
    }
    const b = boundaries[k]
    if (b.base === basePos) return b.side
    return b.side + (basePos - b.base)
  }
}

/**
 * Computes the three-way merge of `mine` and `theirs` against `base`,
 * returning an ordered list of regions.
 *
 * Each region is one of:
 *   { type: 'stable', lines }
 *   { type: 'mine' | 'theirs' | 'both', lines }
 *   { type: 'conflict', mine, base, theirs }
 */
export function computeRegions(mine, base, theirs) {
  const mineChanges = diffAgainstBase(mine, base).map(c => ({ ...c, side: 'mine' }))
  const theirsChanges = diffAgainstBase(theirs, base).map(c => ({ ...c, side: 'theirs' }))

  const mapMine = makeMapper(mineChanges, base.length, mine.length)
  const mapTheirs = makeMapper(theirsChanges, base.length, theirs.length)

  const all = [...mineChanges, ...theirsChanges].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const groups = []
  let idx = 0
  while (idx < all.length) {
    let start = all[idx].baseStart
    let end = all[idx].baseEnd
    idx++
    while (idx < all.length && all[idx].baseStart <= end) {
      if (all[idx].baseEnd > end) end = all[idx].baseEnd
      idx++
    }
    groups.push({ baseStart: start, baseEnd: end })
  }

  const regions = []
  let prevEnd = 0
  for (const g of groups) {
    if (g.baseStart > prevEnd) {
      regions.push({ type: 'stable', lines: base.slice(prevEnd, g.baseStart) })
    }

    const mineLines = mine.slice(mapMine(g.baseStart), mapMine(g.baseEnd))
    const theirsLines = theirs.slice(mapTheirs(g.baseStart), mapTheirs(g.baseEnd))
    const baseLines = base.slice(g.baseStart, g.baseEnd)

    if (arraysEqual(mineLines, theirsLines)) {
      regions.push({ type: 'both', lines: mineLines })
    } else if (arraysEqual(mineLines, baseLines)) {
      regions.push({ type: 'theirs', lines: theirsLines })
    } else if (arraysEqual(theirsLines, baseLines)) {
      regions.push({ type: 'mine', lines: mineLines })
    } else {
      regions.push({ type: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })
    }

    prevEnd = g.baseEnd
  }

  if (prevEnd < base.length) {
    regions.push({ type: 'stable', lines: base.slice(prevEnd, base.length) })
  }

  return regions
}
"}

