{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { computeRegions } from './merge.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function splitInput(input) {
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      parts.push([])
    } else {
      parts[parts.length - 1].push(line)
    }
  }
  return parts
}

function readStdin() {
  const fs = require('fs')
  return fs.readFileSync(0, 'utf8')
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'merge' && mode !== 'merge2' && mode !== 'regions') {
    fail('usage: cli.js merge|merge2|regions')
    return
  }

  const input = readStdinSync()
  const parts = splitInput(input)
  if (parts.length !== 3) {
    fail('expected three parts separated by %%%')
    return
  }

  const [mine, base, theirs] = parts
  const regions = computeRegions(mine, base, theirs)

  let conflict = false
  const out = []

  if (mode === 'regions') {
    for (const region of regions) {
      if (region.type === 'stable' || region.type === 'mine' || region.type === 'theirs' || region.type === 'both') {
        out.push(`${region.type} ${region.lines.length}\n`)
